def main():
 m=json.loads((D/'measurements_v2.json').read_text('utf8'));assert not(D/'report.json').exists()
 for q in m['inputs']:assert sha(ROOT/q['path'])==q['sha256']
 rgb=m['palette_rgb'];mapping=[[i,j]for i in range(1,16)for j in range(1,16)if rgb['0'][i]==rgb['16'][j]];assert mapping==[[13,9]]
 originals=[H/'registered_neutral01/comparison_1.png',H/'registered_neutral01/comparison_2.png',H/'registered_neutral02/comparison_1.png',H/'registered_neutral02/comparison_2.png',H/'reach229_registered01/comparison.png'];uppers=[D/f'readback_v2/upper_{n:03}.png'for n in(221,223,225,227,229)]
 findings=[
 {'ref':221,'visual':'새 두 주먹은 머리 양옆의 높은 손으로 읽히며 귀 내부나 세번째 팔로 보이지 않는다. 머리/앞머리 명암이 늘었지만 대기 대비 과도한 두상 확대나 어깨 절단을 이 판에서 찾지 못했다.','coordinate_evidence':'동일밝은피부색의 오른주먹 bbox는 양폼[0,-25,4,-21), 왼주먹은 기본[-12,-22,-10,-19)/포스[-12,-22,-9,-19). 원부모 오른주먹은[0,-27,4,-23), 왼주먹[-12,-23,-9,-20)로 새손의 높이가 약1~2행 낮아졌다. 얼굴 주피부는 기본[-7,-10,-3,-7)/포스[-7,-10,-2,-6).','common_layer_implication':'주먹은 거의같은위치이나 폭1열/턱끝1행이 이미다르다. 해당새손과얼굴의 의미영역을공통화한뒤커프/목소유경계를검사해야하며, 두전체색인이이미동일하다고가정하지않는다.'},
 {'ref':223,'visual':'한손은 머리뒤로, 다른손은 가슴/턱 아래 가까이 둔 자세로 읽힌다. 높은팔과 머리카락 경계는 유지되며 명백한 팔절단을 못찾았다. 다만 가슴앞 손은 커프와 가까워 현재등록에서 보이는 피부가 작다.','coordinate_evidence':'높은손 밝은피부성분은 기본[-15,-14,-12,-11)/포스[-14,-13,-12,-11). 가슴앞 떨어진밝은피부성분은 두폼[-5,-3,-4,-2) 1셀로, 부모두폼의[-6,-4,-3,-2) 5셀보다 줄었다. 얼굴주피부는 새두폼[-8,-8,-3,-4)로같은bbox이나13/14셀로내부차이가있다.','common_layer_implication':'손가락이없다는확정판정은아니다. 가슴앞손의 실제피부그늘/커프가림을새원화의미영역에서함께확인해야한다. 1셀피부만공통손마스크로쓰거나그주변흰소매를손전체로복사하지않는다.'},
 {'ref':225,'visual':'귀양옆의두낮은주먹과굽힌소매가읽힌다. 새로운추가손이나명백한손목분리는못찾았다. 포스오른손의금색커프와피부색은유사해색만으로손크기를재면오판할수있다.','coordinate_evidence':'화면오른손의확인가능한밝은피부성분은기본[3,-7,5,-5), 포스[4,-6,7,-4)로1열/1행쯤차이가있다. 화면왼손은기본[-14,-8,-11,-5), 포스[-14,-8,-11,-6).','common_layer_implication':'오른손을공통화할때현재포스커프를그대로겹치면1px정도의손목경계가어긋날여지가있다. 이차이만으로전신재작화나팔길이결함이라고판정하지않으며, 새손/커프의전체의미영역을함께정합할항목이다.'},
 {'ref':227,'visual':'양손을가슴앞쪽에낮춘자세가유지되며머리/턱/어깨의명백한절단은못찾았다. 두폼얼굴이완전히동일한위치에등록된것은아니다.','coordinate_evidence':'얼굴주피부는기본[-7,-10,-3,-6)10셀, 포스[-7,-9,-3,-5)10셀로1행다르다. 왼손주피부는두폼[-11,-4,-9,-2)범위. 가슴앞오른손은아주작고포스에밝은피부가2셀더보인다.','common_layer_implication':'기본얼굴/포스몸통을바로합칠때턱/흰칼라경계1행을확인해야한다. 얼굴만옛그림으로덮지말고새머리와선택한공통얼굴/목의연결을유지한다.'},
 {'ref':229,'visual':'국소등록마지막열은양쪽높은주먹과그아래소매가분명하다. 손을귀로읽게했던직전등록보다손/귀구분이명확하며새얼굴/하체는보호된모양으로보인다. 추가세번째손이나손목절단을못찾았다.','coordinate_evidence':'왼주먹밝은피부bbox는두폼[-16,-26,-10,-22)12셀로같다. 오른주먹은기본[3,-25,8,-22)9셀/포스[3,-26,8,-22)13셀로포스상단이1행더있다. 부모의오른주먹[1,-27,4,-23)와는옆으로벌린새해석이므로원좌표exact라고하지않는다.','common_layer_implication':'포스오른팔아래의밝은15셀[2,-21,6,-16)은커프/손목의미가섞일수있다. 피부색성분만으로추가손이라단정하거나머리영역으로보호하지말고팔주변의미경계를나눠야한다.'}
 ]
 r={'read_only':True,'scope':'Root 시부키 PL00 호버221/223/225/227/229의기본(mask8)/포스(mask15) 등록10몸체 얼굴·두손 정적의견. 새층/후보수용/패킹/실기검사아님.','source_parent':m['source'],'inputs':m['inputs'],'measurements':ref(D/'measurements_v2.json'),'old_skin_read':ref(D/'parent_skin_read.json'),'ownership_evidence':ref(W/'zero_audit/shibuki_base_hover_ownership01/conclusions.json'),'actually_viewed':[dict(ref(p),actually_viewed=True)for p in originals+uppers],'palette_constraint':{'opaque_exact_RGB_mapping_base_to_fourth':mapping,'common_RGB':[255,222,189],'meaning':'기본13↔포스9만불투명동일RGB다. raw색인동일성이나양폼피부외15색차이를공통형상불일치의증거로사용하지않는다. 공통0의새얼굴/손과부위의상5/6/7를분리할때색역할도정합해야한다.'},'findings':findings,'summary':'10등록몸에서대기대비명백한머리과대화나새팔절단을찾지못했다. 다만현재얼굴·손은양폼간1px정합차이가있으므로이미공통픽셀이라고가정하면안된다. 223가슴앞손의가림과225오른손목·227턱/칼라·229오른주먹상단을우선경계검토항목으로남긴다.','rejected_diagnostic':'measurements.json의양폼index9동일피부가정은잘못이라초기성분측정을전부배제했다. measurements_v2는실제기본13/포스9의동일RGB를사용. 원본/후보는수정하지않았고기존RGBA비교는각실제팔레트였다.','limits':['표시한bbox는밝은피부색의8연결성분이며손/얼굴전체윤곽이나확정의미마스크가아니다. 좌표끝은exclusive이며원점160의world좌표다.','부모값과차이가있다는사실만으로새미술결함이라판정하지않았다. 새기준후보의공통화선택은Root미술판정과별도다.','원15jet/발접점·하체소유·사격짝·정본총구·부분조합·MIPS·실기검사는HUD/Root범위이며본보고에서재검사하거나통과로확대하지않았다.','제작등록/패킹함수호출과아트/ARC수정없음. 실제10색인과부모재추출·비교10판만읽었다.'],'producer_registration_or_packing_called':False,'art_or_ARC_modified':False,'runtime_verified':False}
 (D/'report.json').write_text(json.dumps(r,ensure_ascii=False,indent=2)+'\n','utf8');files=[D/'read_static.py',Path(__file__).resolve(),D/'report.json',D/'measurements_v2.json',D/'parent_skin_read.json',*originals,*uppers,ROOT/r['ownership_evidence']['path'],*[ROOT/q['path']for q in m['inputs']]];(D/'READER_LOCK.json').write_text(json.dumps({'files':[ref(f)for f in dict.fromkeys(files)]},ensure_ascii=False,indent=2)+'\n','utf8');print(json.dumps({'report_sha256':sha(D/'report.json'),'lock_sha256':sha(D/'READER_LOCK.json'),'actually_viewed':10}))
if __name__=='__main__':main()
